const touchMove={x:0,z:0};let chargeHeld=false;

function burstAt(pos,color,amount=14){for(let i=0;i<amount;i++){const m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95});const mesh=new THREE.Mesh(new THREE.SphereGeometry(.055+Math.random()*.06,7,6),m);mesh.position.copy(pos);scene.add(mesh);bursts.push({mesh,life:.45+Math.random()*.35,v:new THREE.Vector3((Math.random()-.5)*5,Math.random()*5,(Math.random()-.5)*4)});}}
function projectile(from,power=1){const dir=enemy.x>=player.x?1:-1;const isP=from===player;const target=isP?enemy:player;const color=isP?0x5de9ff:0xff5d9b;const mesh=new THREE.Mesh(new THREE.SphereGeometry(.2+power*.18,16,12),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.96}));mesh.position.set(from.x,1.55,from.z);const halo=new THREE.Mesh(new THREE.SphereGeometry(.43+power*.27,14,10),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.21}));mesh.add(halo);scene.add(mesh);const light=new THREE.PointLight(color,3,4);mesh.add(light);projectiles.push({mesh,from,target,dir,power,speed:13+power*4,life:2});}
function trigger(action, fighter=player){if(!started||paused||ended||fighter.dead||fighter.cooldown>0)return;
  if(action==='strike'){fighter.attack=.4;fighter.attackType='strike';fighter.cooldown=.42;fighter.charging=false;if(fighter.isPlayer)lastAction='strike';}
  else if(action==='blast'){if(fighter.ki<22){if(fighter.isPlayer)toastMsg('NOT ENOUGH KI');return;}fighter.ki-=22;fighter.cooldown=.65;fighter.attack=.26;fighter.attackType='blast';projectile(fighter,1);if(fighter.isPlayer)lastAction='blast';}
  else if(action==='dash'){fighter.vx+=(fighter===player?enemy.x-player.x:player.x-enemy.x>0?1:-1)*10;fighter.vz+=(Math.random()-.5)*5;fighter.cooldown=.48;fighter.attack=.2;fighter.attackType='dash';if(fighter.isPlayer)lastAction='dash';}
}
function hit(target,damage,dir){target.hp=Math.max(0,target.hp-damage);target.stun=.26;target.vx+=dir*3.4;target.vz+=(Math.random()-.5)*2;shake=Math.min(.38,shake+.2);burstAt(new THREE.Vector3(target.x,1.55,target.z),target.isPlayer?0xff9269:0x73eaff,15);if(target.hp<=0){target.dead=true;setTimeout(()=>{if(!ended)endGame(target===enemy?'YOU WIN':'YOU LOSE');},550);}}
function attackUpdate(f){if(f.attack>0){const prev=f.attack;f.attack=Math.max(0,f.attack-.016);if(f.attackType==='strike'&&prev>.24&&f.attack<=.24){const t=f===player?enemy:player;if(Math.abs(t.x-f.x)<2.05&&Math.abs(t.z-f.z)<2.1&&t.hp>0)hit(t,10+Math.random()*3,f===player?1:-1);else if(f.isPlayer)toastMsg('WHIFF');}if(f.attackType==='dash'&&prev>.12&&f.attack<=.12){const t=f===player?enemy:player;if(Math.abs(t.x-f.x)<1.9&&Math.abs(t.z-f.z)<1.8)hit(t,12,f===player?1:-1);}}
  if(f.cooldown>0)f.cooldown=Math.max(0,f.cooldown-.016);if(f.stun>0)f.stun=Math.max(0,f.stun-.016);
}
function animateFighter(f,dt){const moving=Math.abs(f.vx)+Math.abs(f.vz)>.7;const t=time*9+(f===player?0:Math.PI);f.body.position.y=f.attackType==='dash'&&f.attack>0?.16:Math.sin(t)*.04*(moving?1.4:.35);f.body.rotation.z=f.attackType==='strike'&&f.attack>0?Math.sin((.4-f.attack)/.4*Math.PI)*-.18:0;
  f.legs.forEach((l,i)=>{l.rotation.x=moving?Math.sin(t+i*Math.PI)*.52:0;});f.arms.forEach((a,i)=>{const s=i===0?-1:1;if(f.attackType==='strike'&&f.attack>0&&s===f.faceSide){const q=Math.sin((.4-f.attack)/.4*Math.PI);a.rotation.z=-f.face*q*1.35;a.rotation.x=-q*.5;}else if(f.charging){a.rotation.x=-.8+Math.sin(t*2)*.08;a.rotation.z=s*.65;}else{a.rotation.x=Math.sin(t*.6+i)*.04;a.rotation.z=s*.12;}});
  f.aura.visible=f.charging||f.ki>94;f.aura.material.opacity=f.charging?.12+Math.sin(t*2)*.05:.08;f.aura.scale.set(1+Math.sin(t*2)*.08,1+Math.sin(t*3)*.07, .72);f.glow.intensity=f.charging?10:0;f.group.rotation.y=f.face>0?Math.PI/2:-Math.PI/2;f.group.position.set(f.x,0,f.z);
}
function update(dt){time-=dt;timerAcc+=dt;if(timerAcc>1&&time>0){timerAcc=0;}if(time<=0&&!ended){time=0;endGame(player.hp>=enemy.hp?'YOU WIN':'YOU LOSE');}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toast.classList.remove('visible');}
  const dx=enemy.x-player.x;player.face=dx>=0?1:-1;enemy.face=-player.face;
  // Player movement. Keyboard and virtual joystick share the same vector.
  let mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+touchMove.x;
  let mz=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+touchMove.z;
  const mlen=Math.hypot(mx,mz);if(mlen>1){mx/=mlen;mz/=mlen;}const speed=keys.has('shift')?7.4:4.7;
  if(player.stun<=0&&started&&!paused){player.vx+=(mx*speed-player.vx)*Math.min(1,dt*9);player.vz+=(mz*speed-player.vz)*Math.min(1,dt*9);if(chargeHeld||keys.has('l')){player.charging=true;player.ki=Math.min(100,player.ki+dt*25);if(Math.random()<dt*12)burstAt(new THREE.Vector3(player.x+(Math.random()-.5),1.6,player.z+(Math.random()-.5)),0x62eaff,1);}else player.charging=false;}
  // Rival keeps pressure, dodges, charges when at range.
  if(enemy.stun<=0&&started&&!paused&&!enemy.dead){const dist=Math.hypot(dx,enemy.z-player.z),approach=dist>2.3?1:dist<1.6?-.18:0;enemy.vx+=(Math.sign(-dx)*approach*3.5-enemy.vx)*Math.min(1,dt*3);enemy.vz+=((player.z-enemy.z)*.65-enemy.vz)*Math.min(1,dt*2);enemy.charging=false;enemy.ai=(enemy.ai||0)-dt;if(enemy.ai<=0){if(dist>4&&enemy.ki<70&&Math.random()<.54){enemy.charging=true;enemy.ki=Math.min(100,enemy.ki+dt*18);enemy.ai=.65;}else if(dist<2.5&&Math.random()<.65){trigger('strike',enemy);enemy.ai=.75+Math.random()*.3;}else if(enemy.ki>=22&&dist<8){trigger('blast',enemy);enemy.ai=1.1;}else{enemy.ai=.4;}}if(enemy.charging&&enemy.ai<.15)enemy.charging=false;}
  for(const f of fighters){f.x+=f.vx*dt;f.z+=f.vz*dt;f.vx*=Math.pow(.025,dt);f.vz*=Math.pow(.025,dt);f.x=THREE.MathUtils.clamp(f.x,-8.7,8.7);f.z=THREE.MathUtils.clamp(f.z,-7.7,7.7);attackUpdate(f);animateFighter(f,dt);}
  // Keep fighters from occupying the same space.
  const separation=player.x-enemy.x;if(Math.abs(separation)<.85&&Math.abs(player.z-enemy.z)<.8){const push=(.85-Math.abs(separation))*.5;player.x+=Math.sign(separation||-1)*push;enemy.x-=Math.sign(separation||-1)*push;}
  for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;p.mesh.position.x+=p.dir*p.speed*dt;p.mesh.position.y=1.55+Math.sin(time*8+i)*.08;if(Math.abs(p.mesh.position.x-p.target.x)<.55&&Math.abs(p.mesh.position.z-p.target.z)<1&&p.life>0){hit(p.target,12+p.power*3,p.dir);burstAt(p.mesh.position,p.from===player?0x6cecff:0xff72a8,20);p.life=0;}if(p.life<=0){scene.remove(p.mesh);projectiles.splice(i,1);}}
  for(let i=bursts.length-1;i>=0;i--){const b=bursts[i];b.life-=dt;b.mesh.position.addScaledVector(b.v,dt);b.v.y-=5*dt;b.mesh.material.opacity=Math.max(0,b.life);b.mesh.scale.multiplyScalar(1+dt*2);if(b.life<=0){scene.remove(b.mesh);b.mesh.geometry.dispose();b.mesh.material.dispose();bursts.splice(i,1);}}
  // Cinematic camera tracks both warriors, including vertical framing on phones.
  const midX=(player.x+enemy.x)*.5,midZ=(player.z+enemy.z)*.5;const portrait=innerHeight>innerWidth;
  const desired=new THREE.Vector3(midX,portrait?8.3:6.7,midZ+(portrait?14:12.4));camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(midX,1.25,midZ-.2);
  if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake;shake=Math.max(0,shake-dt*.75);}dust.rotation.y+=dt*.012;
  if(Math.random()<dt*.55){const x=(Math.random()-.5)*19,z=(Math.random()-.5)*14;const c=new THREE.Mesh(new THREE.SphereGeometry(.025,6,6),new THREE.MeshBasicMaterial({color:'#fff1d2'}));c.position.set(x,.1,z);scene.add(c);bursts.push({mesh:c,life:1.6,v:new THREE.Vector3(0,.35,0)});}
  updateHud();
}

const clock=new THREE.Clock();function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.035);if(started&&!paused&&!ended)update(dt);else{time-=0;animateFighter(player,dt);animateFighter(enemy,dt);camera.lookAt(0,1.25,0);}renderer.render(scene,camera);}
